(function() {
    let eventBus = document.createElement("b"); // Ultralight doesn't like constructing EventTarget directly

    window.lunarInternalAccept = function(name, data) {
        eventBus.dispatchEvent(new CustomEvent(name, {detail: data}));
    };
    window.lunarReady = {READY};
    window.lunar = new Proxy({
            subscribe(name, cb) {
                eventBus.addEventListener(name, cb);
            },
            unsubscribe(name, cb) {
                eventBus.removeEventListener(name, cb);
            }
        }, {
            get(obj, prop) {
                if (obj.hasOwnProperty(prop)) return obj[prop];
                return async (...args) => {
                    let val = window[`lunarInternalInvoke`](prop, ...args);
                    if (typeof val === 'symbol') return "";
                    return val;
                };
            }
        });
})();
